module up_down_counter(
    input clk,
    input reset,
    input up_down,
    output reg [3:0] count
);
    always @(posedge clk or posedge reset) begin
        if (reset)
            count <= 4'd0;
        else if (up_down)
            count <= count + 1;
        else
            count <= count - 1;
    end
endmodule

