          2'b10: sseg = in2;
          2'b11: sseg = in3;
        endcase
        case(state1)
          2'b00: begin an = 4'b1110; dp = 1; end 
          2'b01: begin an = 4'b1101; dp = 1; end
          2'b10: begin an = 4'b1011; dp = 0; end
          2'b11: begin an = 4'b0111; dp = 1; end
        endcase
    end

    always @(posedge clk) begin
        state1 <= nextstate;
    end
endmodule

