description:
Design a circuit that decodes a 4-bit binary input representing a numeral (0-9) and outputs the equivalent signals to drive a 7-segment display. The output consists of 7 bits controlling the segments of the display, with specific arrangements corresponding to each numeral. If the input is outside the range of 0-9, it defaults to illuminating the middle segment only.
module top_module(
	input [3:0] numberToDecode,
	output reg [6:0] digitLeds
    );

code:
module top_module(
	input [3:0] numberToDecode,
	output reg [6:0] digitLeds
    );parameter ZERO = 7'b0000001;
parameter ONE = 7'b1001111;
parameter TWO = 7'b0010010;
parameter THREE = 7'b0000110;
parameter FOUR = 7'b1001100;
parameter FIVE = 7'b0100100;
parameter SIX = 7'b0100000;
parameter SEVEN = 7'b0001111;
parameter EIGHT = 7'b0000000;
parameter NINE = 7'b0000100;
parameter showMiddleLed = 7'b0000001;












always @ (numberToDecode)

	begin

		case(numberToDecode)













			0: digitLeds = ZERO;
			1: digitLeds = ONE;
			2: digitLeds = TWO;
			3: digitLeds = THREE;
			4: digitLeds = FOUR;
		   5: digitLeds = FIVE;
			6: digitLeds = SIX;
			7: digitLeds = SEVEN;
			8: digitLeds = EIGHT;
			9: digitLeds = NINE;

			default:digitLeds = showMiddleLed;

		endcase

	end

endmodule

