assign prod4={1'b0,{x[15]&y[15]},{13{1'b0}},path,{15{1'b0}}}; 
assign product=(prod1+prod2)+(prod3+prod4); 

always@(x[15] or y[15])begin 
case({x[15],y[15]}) 
2'b00:path=2'b00; 
2'b01:path=2'b01; 
2'b10:path=2'b01; 
2'b11:path=2'b10; 
endcase 
end 

